INSERT INTO reviews.entity_reviews (id, target_entity_id, target_entity_type, reviewer_user_id, project_id, rating, title, comment, created_at, updated_at)
VALUES
  ('ffab25db-596a-4800-a4cd-b961c3b0ee56', 'edc2d943-8062-426a-a6f2-29fdc6b4363c', 'team', '292e1827-f189-4f34-ab35-27c9f0320926', '7f930a97-cfa8-4784-a7d0-61c913c2f3ce', 4.80, 'Reliable, communicative, and the load test held', 'North Loop delivered the ingestion stage a week early and the replay design has already saved us once. Communication was proactive throughout and the handoff notes were the best we have received from an outside team.', now() - interval '456 hours', now() - interval '456 hours'),
  ('ce36196d-459a-4cdc-ad8e-860354220ac2', '4cfa4f66-9aa2-496b-a93d-994caac019c1', 'business', 'c7173d3f-8b15-4876-afbf-499d17513a44', '7f930a97-cfa8-4784-a7d0-61c913c2f3ce', 5.00, 'A client who reviews on time', 'Daniel reviewed every submission within a day, gave specific feedback, and released escrow the moment a stage was accepted. Atlas is exactly the kind of client a small studio wants to keep working with.', now() - interval '432 hours', now() - interval '432 hours'),
  ('5945fbee-18f9-41dd-a039-eac8b836f61f', '6ce1906f-caab-4708-a19e-df3d8960666e', 'freelancer', '35ce4987-15b3-4c38-a438-2bb9c35df15a', 'af6c1867-2b94-49f4-ad1f-12c10c4ab616', 5.00, 'The token work engineering actually adopted', 'Maris delivered a token architecture our engineers adopted the same week, with a theming contract that made dark mode a configuration change rather than a project. Clear communication, on time, and thoughtful about accessibility throughout.', now() - interval '336 hours', now() - interval '336 hours'),
  ('e9047f5f-6146-48ea-a0c2-5b9d04e86608', 'edb582e0-25d2-48a3-a0db-4a96f1d1a8d1', 'business', '6ce1906f-caab-4708-a19e-df3d8960666e', 'af6c1867-2b94-49f4-ad1f-12c10c4ab616', 4.70, 'Well-run, fast reviews', 'Helia is a well-run client: the brief was clear, reviews came back within two days, and payment was released promptly once a stage was accepted. Occasional scope creep in the details stage, but always negotiated in the open.', now() - interval '312 hours', now() - interval '312 hours')
